describe('Deep Link Navigation', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should load the correct page when deep linking with valid path', () => {
    // Navigate to deep link
    cy.visit('/dashboard/users/123');

    // Verify page title is set correctly
    cy.title().should('include', 'User Profile - Dashboard');

    // Verify user profile section is visible
    cy.get('[data-testid="user-profile-section"]').should('be.visible');

    // Verify user details are displayed
    cy.get('[data-testid="user-name"]').should('contain', 'John Doe');
    cy.get('[data-testid="user-email"]').should('contain', 'john.doe@example.com');

    // Verify navigation back to dashboard works
    cy.go('back');
    cy.url().should('include', '/dashboard');
  });

  it('should handle invalid deep link paths and redirect to 404 page', () => {
    // Attempt to navigate to an invalid deep link
    cy.visit('/dashboard/users/abc123');

    // Verify redirection to 404 page
    cy.url().should('include', '/404');

    // Verify 404 page title is set
    cy.title().should('include', '404 - Page Not Found');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid user ID');

    // Verify navigation back to dashboard works
    cy.go('back');
    cy.url().should('include', '/dashboard');
  });
});
